using System;using System.IO;using System.Linq;using System.Text;using System.Reflection;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEngine.SceneManagement;
[InitializeOnLoad]public static class FinalGoldBridgeAudit{
static BindingFlags F=BindingFlags.Static|BindingFlags.NonPublic;static V Get<V>(object o,string n)=>(V)o.GetType().GetField(n).GetValue(o);
static FinalGoldBridgeAudit(){EditorApplication.update+=Poll;}static void Poll(){if(!File.Exists("FinalGoldBridgeAudit.request")||EditorApplication.isCompiling)return;File.Delete("FinalGoldBridgeAudit.request");try{var scene=SceneManager.GetSceneByPath("Assets/Editor/DayNightBackups/Gangstar Final Env.unity");var rs=scene.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<MeshRenderer>(true)).Where(r=>r.enabled&&r.gameObject.activeInHierarchy&&r.GetComponent<MeshFilter>()).ToArray();var log=new StringBuilder();foreach(var r in rs.Where(r=>!r.transform.root.name.StartsWith("City Building Signs")&&!r.sharedMaterials.Any(m=>m&&m.name.StartsWith("Building"))&&r.bounds.max.y>32&&r.bounds.size.y>.2&&r.bounds.size.y<24&&Mathf.Max(r.bounds.size.x,r.bounds.size.z)>18&&Mathf.Max(r.bounds.size.x,r.bounds.size.z)<180))log.AppendLine("POSSIBLE BRIDGE "+r.name+" "+r.bounds+" materials="+string.Join("|",r.sharedMaterials.Select(m=>m?m.name:"null")));
var textures=new Dictionary<Texture,Texture2D>();var gold=new List<Tuple<MeshRenderer,float>>();foreach(var r in rs.Where(r=>r.sharedMaterial&&r.sharedMaterial.name.StartsWith("Building")&&r.bounds.size.y>18).GroupBy(r=>r.GetComponent<MeshFilter>().sharedMesh).Select(g=>g.First())){var mat=r.sharedMaterial;var tex=mat.HasProperty("_BaseMap")?mat.GetTexture("_BaseMap"):mat.mainTexture;if(!tex)continue;if(!textures.TryGetValue(tex,out var image)){string path=AssetDatabase.GetAssetPath(tex);image=new Texture2D(2,2);if(!File.Exists(path)||!image.LoadImage(File.ReadAllBytes(path))){UnityEngine.Object.DestroyImmediate(image);continue;}textures[tex]=image;}var data=typeof(FinalPNGCityDetails).GetMethod("Read",F).Invoke(null,new object[]{r.GetComponent<MeshFilter>().sharedMesh});var uv=Get<Vector2[][]>(data,"uv")[0];int warm=0,count=0;for(int i=0;i<uv.Length;i+=Mathf.Max(1,uv.Length/300)){var col=image.GetPixelBilinear(uv[i].x,uv[i].y);if(col.r>.35f&&col.g>.18f&&col.g>col.b+.08f&&col.r>col.g*.98f)warm++;count++;}gold.Add(Tuple.Create(r,warm/(float)Mathf.Max(1,count)));}
int k=0;foreach(var g in gold.OrderByDescending(v=>v.Item2).Take(5)){var r=g.Item1;log.AppendLine("GOLD "+k+" "+r.name+" score="+g.Item2+" "+r.bounds);var p=r.bounds.center;typeof(FinalPNGCityDetails).GetMethod("Capture",F).Invoke(null,new object[]{scene,p+new Vector3(r.bounds.size.x,r.bounds.size.y*.15f,-r.bounds.size.z*1.5f),p,"Gold-Model-"+k});k++;}foreach(var tex in textures.Values)UnityEngine.Object.DestroyImmediate(tex);File.WriteAllText("FinalEnvironmentRoadReview/GoldBridgeAudit.txt",log.ToString());}catch(Exception e){File.WriteAllText("FinalEnvironmentRoadReview/GoldBridgeAudit.txt","FAILED "+e);Debug.LogException(e);}}}
